                return funkey.seq(items).filter(predicate).list()
            except Exception:
                # If funkey is present but we can't call it as above, fall back.
                return [it for it in items if predicate(it)]
    except ImportError:
        # funkey not installed; use plain Python
        return [it for it in items if predicate(it)]

