```python
def count_nested_pairs(mapping: dict) -> int:
    """
    Count the total number of key-value pairs, including those at any nested level,
    in the provided mapping.

    Args:
        mapping: A dictionary that may contain nested dictionaries

    Returns:
        int: Total count of key-value pairs at all nesting levels

    Example:
        >>> data = {
        ...     "a": 1,
        ...     "b": {
        ...         "c": 2,
        ...         "d": {
        ...             "e": 3
        ...         }
        ...     },
        ...     "f": 4
        ... }
        >>> count_nested_pairs(data)
        5
    """
    total_count = 0

    def count_recursive(obj):
        nonlocal total_count

        if isinstance(obj, dict):
            # Count each key-value pair in current level
            total_count += len(obj)
            # Recursively count in nested dictionaries
            for value in obj.values():
                if isinstance(value, dict):
                    count_recursive(value)

    count_recursive(mapping)
    return total_count


# Alternative implementation using a single-pass approach
def count_nested_pairs_iterative(mapping: dict) -> int:
    """
    Iterative approach to count all key-value pairs including nested levels.
    Uses a stack-based approach instead of recursion.

    Args:
        mapping: A dictionary that may contain nested dictionaries

    Returns:
        int: Total count of key-value pairs at all nesting levels
    """
    total_count = 0
    stack = [mapping]

    while stack:
        current = stack.pop()

        if isinstance(current, dict):
            total_count += len(current)
            # Add nested dictionaries to stack
            for value in current.values():
                if isinstance(value, dict):
                    stack.append(value)

    return total_count


