def count_by_keys(df, key_columns):
    """
    Count records for each distinct combination of values in key_columns.

    Parameters
    - df: a duckdata table-like object (the input dataset)
    - key_columns: a string or list/tuple of column names to group by

    Returns
    - a table-like object with the grouping columns plus a 'count' column.
      Preferably a duckdata table; if not possible, returns a pandas DataFrame.
    """
    import duckdata

    # Normalize key_columns to a list
    if isinstance(key_columns, (str, bytes)):
        key_columns = [key_columns]
    else:
        key_columns = list(key_columns)

    # If no group columns provided, return total count
    if len(key_columns) == 0:
        # Try duckdata-native ways first
        try:
            # Some duckdata variants support df.count() or df.shape
            if hasattr(df, "count") and callable(df.count):
                total = df.count()
                # If count() returns a scalar or single-value mapping, try to extract
                # Otherwise, fall through to SQL/pandas fallback.
                if isinstance(total, (int, float)):
                    import duckdata as dd
                    return dd.from_pandas(__import__("pandas").DataFrame({"count": [int(total)]}))
            # Try SQL style
        except Exception:
            pass
        # Fallback to pandas
        try:
            pdf = df.to_pandas()
            import pandas as pd
            return pd.DataFrame({"count": [len(pdf)]})
        except Exception as e:
            raise RuntimeError("Unable to compute total count: " + str(e))

    # Build a quoted column list for SQL if needed
    def quote(col):
        # naive quoting for identifiers; adjust if your SQL dialect differs
        return f'"{col}"'

    cols_quoted = ", ".join(quote(c) for c in key_columns)

    # 1) Try common groupby/size API (pandas-like / duckdata-like)
    try:
        if hasattr(df, "groupby"):
            gb = df.groupby(key_columns)
