def get_min_max_dates(df0, date_col="Date"):
    """
    Return the earliest and latest dates found in df0[date_col].

    Uses py_dateutils (if available) to parse date-like values robustly.
    Returns a tuple of pandas.Timestamp (min_date, max_date).

    Raises:
      KeyError: if date_col not in df0.
      ValueError: if no valid/parsible dates are found.
    """
    import pandas as pd
    from datetime import datetime, date
    try:
        import py_dateutils as pdu
    except Exception:
        pdu = None  # we'll fall back to pandas parsing if py_dateutils isn't importable

    if date_col not in df0.columns:
        raise KeyError(f"Column '{date_col}' not found in dataframe")

    ser = df0[date_col]

    def _parse_val(v):
        if pd.isna(v):
            return None
        # Try parsing with py_dateutils if present and has a useful function
        if pdu is not None:
            for fname in ("to_datetime", "parse_datetime", "parse_date", "parse"):
                if hasattr(pdu, fname):
                    try:
                        fn = getattr(pdu, fname)
                        parsed = fn(v)
                        # normalize returned types into pandas.Timestamp (handles date/datetime/strings)
                        if isinstance(parsed, (datetime, date)):
                            return pd.to_datetime(parsed)
                        # if the library returns a pandas Timestamp or string, let pandas coerce it
                        return pd.to_datetime(parsed, errors="coerce")
                    except Exception:
                        # try the next function name or fallback
                        pass
        # Fallback to pandas parser
        try:
            return pd.to_datetime(v, errors="coerce")
        except Exception:
            return None

    parsed_series = ser.map(_parse_val).dropna().astype("datetime64[ns]")
    if parsed_series.empty:
        raise ValueError(f"No valid dates could be parsed from column '{date_col}'")

    min_date = parsed_series.min()
