        except Exception:
            ds = None
    if ds is None and hasattr(modelin_client, 'load_dataset'):
        try:
            ds = modelin_client.load_dataset(dataset_name)
        except Exception:
            ds = None

    if ds is None:
        raise RuntimeError(f"Could not fetch dataset '{dataset_name}' from the provided modelin_client")

    # 2) Convert to pandas DataFrame (try several common attributes)
    if isinstance(ds, pd.DataFrame):
        df = ds.copy()
        ds_is_pandas = True
    else:
