        ds_is_pandas = False
        for attr in ('to_pandas', 'as_pandas', 'dataframe', 'df'):
            if hasattr(ds, attr):
                try:
                    candidate = getattr(ds, attr)
                    if callable(candidate):
                        df = candidate()
                    else:
                        df = candidate
                except Exception:
                    df = None
                if isinstance(df, pd.DataFrame):
                    break
        # if still None, try modelin_client-level conversion
        if df is None and hasattr(modelin_client, 'to_pandas'):
            try:
                df = modelin_client.to_pandas(ds)
