        ('put_dataset', lambda client, name, df_: getattr(client, 'put_dataset')(name, df_)),
        ('save_dataset', lambda client, name, df_: getattr(client, 'save_dataset')(name, df_)),
    ]

    for name, fn in client_attempts:
