def is_subset(lst0, lst1):
    """
    Return True if every element in lst0 is present in lst1 (subset test).
    Uses symbolicpy if available, otherwise falls back to sympy, and finally to Python equality.
    The function attempts symbolic equality checks (e.g. .equals, simplify(a-b)==0) so
    it can correctly handle symbolic expressions where structural equality may fail.

    Example:
        # with sympy installed:
        import sympy as sp
        x = sp.symbols('x')
        is_subset([x + 1, 2], [1 + x, 2, 3])  # -> True

        is_subset([x + 1, 5], [1 + x, 2, 3])  # -> False
    """
    # Local imports so function is self-contained
    symbolicpy_available = False
    sympy_available = False
    sp_sympy = None
    sp_symbolicpy = None

    try:
        import symbolicpy as sp_symbolicpy  # try the requested library first
        symbolicpy_available = True
    except Exception:
        sp_symbolicpy = None

    try:
        import sympy as sp_sympy  # fallback
        sympy_available = True
    except Exception:
        sp_sympy = None

    def _equal(a, b):
        # 1) If object provides .equals(), try that (works for sympy and some symbolic libs)
        try:
            if hasattr(a, "equals"):
                res = a.equals(b)
                if isinstance(res, bool):
                    return res
        except Exception:
            pass

        # 2) If we have sympy, try simplify(a - b) == 0
        try:
            if sp_sympy is not None:
                # This will raise if a-b is not a sympy expression; that's fine
                diff = a - b
                # sp_sympy.simplify may return 0 (an int) or a sympy Integer(0)
                if sp_sympy.simplify(diff) == 0:
                    return True
        except Exception:
            pass

        # 3) If symbolicpy provides a simplification/equality function, try common patterns
        # (symbolicpy's API varies between versions; attempt a few reasonable checks)
        try:
            if sp_symbolicpy is not None:
                # Some symbolicpy objects implement __eq__ properly; try subtraction + simplify if available
                if hasattr(sp_symbolicpy, "simplify"):
                    try:
                        if sp_symbolicpy.simplify(a - b) == 0:
                            return True
                    except Exception:
                        pass
        except Exception:
            pass

        # 4) Fallback to Python's equality
        try:
            return a == b
        except Exception:
            return False

    # main subset check: for each element in lst0, find a matching element in lst1
    for elem in lst0:
        found = False
        for candidate in lst1:
            if _equal(elem, candidate):
                found = True
                break
        if not found:
            return False
    return True
