def sort_by_key(iterable, key=None):
    """
    Return a new list containing the elements of `iterable`, sorted according to `key`.

    This function attempts to use a SortedList / SortedListWithKey implementation from
    common packages (sortedcontainers, sortedlist, sortedlists). If such a library
    isn't available it falls back to the built-in sorted().

    Parameters
    - iterable: any iterable of items to sort
    - key: optional callable(item) -> value used to compare items

    Returns
    - list of items sorted according to key
    """
    items = list(iterable)

    # Try to find a SortedList-like class
    SortedListWithKey = None
    SortedListNoKey = None
    # Try common package/class names in order of preference
    try:
        from sortedcontainers import SortedListWithKey as SortedListWithKey  # preferred
    except Exception:
        SortedListWithKey = None

    if SortedListWithKey is None:
        try:
            # Some versions expose a different name
            from sortedcontainers import SortedKeyList as SortedListWithKey
        except Exception:
            SortedListWithKey = None

    if SortedListWithKey is None:
        # Try generic SortedList (no key param)
        try:
            from sortedcontainers import SortedList as SortedListNoKey
        except Exception:
            SortedListNoKey = None

    # Try alternative libraries that might be named differently
    if SortedListWithKey is None and SortedListNoKey is None:
        try:
            from sortedlist import SortedList as SortedListNoKey
        except Exception:
            SortedListNoKey = None
    if SortedListWithKey is None and SortedListNoKey is None:
        try:
            # some packages use 'sortedlists'
            from sortedlists import SortedList as SortedListNoKey
        except Exception:
            SortedListNoKey = None
    if SortedListWithKey is None and SortedListNoKey is None:
        try:
            from sortedlists import SortedListWithKey as SortedListWithKey
        except Exception:
            SortedListWithKey = None

    # If we have a SortedListWithKey that accepts a key parameter, use it
    if SortedListWithKey is not None:
        try:
            sorted_list = SortedListWithKey(items, key=key)
            return list(sorted_list)
        except TypeError:
            # maybe this variant doesn't accept iterable+key in constructor; try add individually
            sl = SortedListWithKey(key=key)
            for it in items:
                sl.add(it)
            return list(sl)

    # If we have a SortedList without native key support, decorate with key to sort
    if SortedListNoKey is not None:
        if key is None:
            # Directly use the SortedList to sort by item values
            sorted_list = SortedListNoKey(items)
            return list(sorted_list)
        else:
            # decorate with (key(item), index, item) to ensure stability and proper ordering
            decorated = [(key(x), idx, x) for idx, x in enumerate(items)]
            sorted_decorated = SortedListNoKey(decorated)
            return [t[2] for t in sorted_decorated]

    # If no external library found, fall back to built-in sorted
    return sorted(items, key=key)
