    pattern = re.compile(r'[^A-Za-z0-9]+')

    # make a copy of the DataFrame so original is not mutated
    df = df0.copy()

    # helper to clean a single value using the regex fallback
    def _clean_with_regex(val):
        if pd.isna(val):
            return val
        return pattern.sub('', str(val))

    # Try to use pysanitizer if available
    try:
        import pysanitizer as ps  # attempt import
    except Exception:
        ps = None

    if ps is not None:
        # try a few common function names and invocation patterns that some sanitizer libs use.
        # If a matching callable is found and works, use it; otherwise fall back to regex.
        cleaned = None
        for fname in ('sanitize', 'clean', 'sanitize_string', 'clean_text'):
            fn = getattr(ps, fname, None)
            if not callable(fn):
                continue
            try:
                # attempt common signature: fn(text, pattern=..., repl=...)
                def _try_fn(x):
                    if pd.isna(x):
                        return x
                    return fn(str(x), pattern=r'[^A-Za-z0-9]', repl='')
                cleaned = df[col_name].apply(_try_fn)
                break
            except TypeError:
                # try alternative signature: fn(text, pattern, repl)
                try:
                    def _try_fn2(x):
                        if pd.isna(x):
