                        return fn(str(x), r'[^A-Za-z0-9]', '')
                    cleaned = df[col_name].apply(_try_fn2)
                    break
                except Exception:
                    continue
            except Exception:
                continue

        if cleaned is not None:
            df[col_name] = cleaned
            return df

    # Fallback: use regex replacement (robust and predictable)
    df[col_name] = df[col_name].apply(_clean_with_regex)
