import pandas as pd
import numpy as np

def percent_missing_per_column_using_misinfo(df0):
    """
    Return the percentage (0-100) of missing entries for each column in df0,
    attempting to use the `misinfo` library if available, and falling back to
    a pandas-based computation otherwise.

    Parameters
    ----------
    df0 : array-like or pandas.DataFrame
        Two-dimensional dataset (rows x columns). Can be a pandas DataFrame,
        a NumPy array, or anything convertible to pd.DataFrame.

    Returns
    -------
    pandas.Series
        Index is column names (or numeric indices if input was not a DataFrame),
        values are floats giving the percentage of missing values in that column.

    Notes
    -----
    This function probes for commonly named functions in `misinfo` (e.g.
    missing_percentage, missing_fraction, missing_percent, missing_rate,
    missingness). If none are present or usable, it computes missingness via
    pandas: (df.isna().mean() * 100).
    """
    # Ensure data is a DataFrame
    df = pd.DataFrame(df0)

    # Try to import misinfo and use any common API if present
    try:
        import misinfo
    except Exception:
        misinfo = None

    def _to_series_and_percent(res):
        """Normalize result to a pandas Series of percentages (0-100)."""
        # If it's a dict-like
        if isinstance(res, dict):
            s = pd.Series(res)
        # If it's already a pandas Series
        elif isinstance(res, pd.Series):
            s = res.copy()
        # If it's a numpy array or list or DataFrame row/col
        elif isinstance(res, (np.ndarray, list, tuple, pd.DataFrame)):
            s = pd.Series(np.asarray(res))
        else:
            # last resort: try to construct series directly
            try:
                s = pd.Series(res)
            except Exception:
                raise ValueError("Could not interpret misinfo output as a sequence/dict/Series")

        # If values look like fractions in [0,1], convert to percent
        if s.dropna().shape[0] > 0:
            vmin, vmax = s.min(), s.max()
            if vmin >= 0 and vmax <= 1.000001:
                s = s * 100.0
        # Align index to dataframe columns if lengths match and index is numeric
        if len(s) == df.shape[1]:
            # if s has integer index 0..n-1, replace with df.columns
            if s.index.equals(pd.RangeIndex(len(s))):
                s.index = df.columns
        return s.astype(float)

    # If misinfo is present, try a few plausible function names
    if misinfo is not None:
        # list of candidate callables; some might accept (df, axis=0) or (df,)
        candidates = [
            'missing_percentage', 'missing_percent', 'missing_fraction',
            'missing_frac', 'missing_rate', 'missingness', 'column_missing_percentage',
            'column_missing_percent'
        ]
        for name in candidates:
            fn = getattr(misinfo, name, None)
            if callable(fn):
                # Try calling in a few ways
                for call_kwargs in ({'df': df}, {'data': df}, {'X': df}, {}):
                    try:
                        # Prefer passing df as the first positional arg if kwargs empty
                        if call_kwargs:
                            res = fn(**call_kwargs)
                        else:
                            res = fn(df)
                        # Normalize and return if successful
                        return _to_series_and_percent(res)
                    except TypeError:
                        # try other signature attempts (axis keyword)
                        try:
                            res = fn(df, axis=0)
                            return _to_series_and_percent(res)
                        except Exception:
                            continue
                    except Exception:
                        # any other exception: try next candidate
                        break
        # If we get here, misinfo present but no suitable function returned usable result;
        # fall back to pandas computation.

    # Fallback computation using pandas
    percent_missing = df.isna().mean(axis=0) * 100.0
    # Ensure float dtype
    return percent_missing.astype(float)


