def count_unique_values(df0: mpd.DataFrame, lst0: Iterable[str], dropna: bool = False, sort: bool = True) -> Dict[str, mpd.DataFrame]:
    """
    Count occurrences of each unique value in each column listed in lst0 from df0 (modin DataFrame).

    Parameters:
    - df0: a modin DataFrame
    - lst0: iterable of column names (strings) to count values for
    - dropna: whether to exclude NA/null values from the counts (default False)
    - sort: whether to sort results by count descending (default True)

    Returns:
    - dict mapping column name -> modin DataFrame with columns:
        ['value', 'count'] (value = unique value, count = occurrence count)
    """
    if isinstance(lst0, str):
        lst0 = [lst0]
    result: Dict[str, mpd.DataFrame] = {}

    for col in lst0:
        if col not in df0.columns:
            raise KeyError(f"Column '{col}' not found in DataFrame")

        # Preferred approach: use value_counts if available
        try:
            vc = df0[col].value_counts(dropna=dropna)  # Series: index = values, values = counts
            df_counts = vc.rename("count").reset_index().rename(columns={"index": "value"})
        except Exception:
            # Fallback: groupby + size
            df_counts = df0.groupby(col).size().reset_index(name="count")
            if dropna:
                df_counts = df_counts[df_counts[col].notna()].copy()
            df_counts = df_counts.rename(columns={col: "value"})

        if sort:
            df_counts = df_counts.sort_values("count", ascending=False).reset_index(drop=True)
        else:
            # ensure consistent column order
            if "value" not in df_counts.columns and col in df_counts.columns:
                df_counts = df_counts.rename(columns={col: "value"})

        # ensure resulting frame columns are ['value', 'count']
        if list(df_counts.columns) != ["value", "count"]:
            # try to coerce to that shape
            cols = list(df_counts.columns)
            # find count column
            if "count" not in cols:
                # assume second column is count
                df_counts = df_counts[[cols[0], cols[1]]].rename(columns={cols[0]: "value", cols[1]: "count"})
            else:
                # ensure 'value' column exists
                if "value" not in cols:
                    first_non_count = [c for c in cols if c != "count"][0]
                    df_counts = df_counts[[first_non_count, "count"]].rename(columns={first_non_count: "value"})
                else:
                    df_counts = df_counts[["value", "count"]]

        result[col] = df_counts

    return result

