def check_var0(var0) -> Tuple[bool, Optional[str]]:
    """
    Check whether var0 is:
      - a native sequence type (list/tuple/deque/range/etc but NOT str/bytes),
      - a multidimensional numeric collection (e.g. numpy.ndarray or torch.Tensor with ndim>1,
        or a nested numeric Python sequence with depth > 1),
      - a one-dimensional labeled data sequence (pandas.Series or xarray.DataArray with 1D).

    Returns:
      (True, category) if any of the above holds, where category is one of:
        'one_dim_labeled', 'multidim_numeric', 'native_sequence'
      Otherwise returns (False, None).

    Notes:
      - Requires torchmesh to be importable (imported at module import).
      - numpy/torch/pandas/xarray are optional; if not installed, checks that depend on them are skipped.
    """

    # Helpers
    def is_native_sequence(obj) -> bool:
        # Accept any collections.abc.Sequence except str/bytes/bytearray and except numpy arrays / torch tensors
        if isinstance(obj, (str, bytes, bytearray)):
            return False
        # Exclude mappings
        if isinstance(obj, cabc.Mapping):
            return False
        # Exclude numpy arrays and torch tensors (they are sequence-like but handled separately)
        if np is not None and isinstance(obj, np.ndarray):
            return False
        if torch is not None and isinstance(obj, torch.Tensor):
            return False
        return isinstance(obj, cabc.Sequence)

    def is_pandas_series(obj) -> bool:
        return pd is not None and isinstance(obj, pd.Series)

    def is_xarray_1d(obj) -> bool:
        return xr is not None and isinstance(obj, xr.DataArray) and obj.ndim == 1

    def is_one_dim_labeled(obj) -> bool:
        if is_pandas_series(obj):
            return True
        if is_xarray_1d(obj):
            return True
        return False

    def is_numpy_multidim(obj) -> bool:
        return np is not None and isinstance(obj, np.ndarray) and obj.ndim > 1

    def is_torch_multidim(obj) -> bool:
        return torch is not None and isinstance(obj, torch.Tensor) and obj.dim() > 1

    def is_numeric_scalar(x) -> bool:
        # numpy scalar handled by np.isscalar if available
        if np is not None:
            try:
                if np.isscalar(x):
                    return True
            except Exception:
                pass
        # torch scalar tensor: 0-dim tensor
        if torch is not None and isinstance(x, torch.Tensor):
            return x.dim() == 0 and x.numel() == 1
        # Python numeric types
        return isinstance(x, numbers.Number)

    # For nested python sequences, determine whether leaves are numeric and compute nesting depth > 1
    def nested_numeric_depth_gt_one(obj) -> bool:
        # returns True if obj is a sequence (not str/bytes) whose leaves are numeric and nesting depth > 1
        def depth_and_all_numeric(o, current_depth=0):
            # if o is a numpy array or torch tensor, treat separately
            if np is not None and isinstance(o, np.ndarray):
                # if numpy array, we consider leaf numeric if dtype is numeric
                if o.dtype.kind in 'biufc':  # boolean, integer, unsigned, float, complex
                    return (o.ndim, True)
                return (0, False)
            if torch is not None and isinstance(o, torch.Tensor):
                # numeric if tensor dtype is floating/integer/bool
                try:
                    kind = o.dtype
                    # treat as numeric if dtype is a torch number dtype
                    return (o.dim(), True)
                except Exception:
                    return (0, False)

            if isinstance(o, (str, bytes, bytearray)):
                return (0, False)
            if isinstance(o, cabc.Mapping):
                return (0, False)
            if isinstance(o, cabc.Sequence):
                # empty sequence: cannot determine leaves here - treat as not numeric
                if len(o) == 0:
                    return (1, False)
                max_depth = current_depth
                all_numeric = True
                for item in o:
                    d, numeric = depth_and_all_numeric(item, current_depth + 1)
                    if d > max_depth:
                        max_depth = d
                    if not numeric:
                        all_numeric = False
                return (max_depth - current_depth + 1, all_numeric)
            # leaf
            return (0, is_numeric_scalar(o))

        depth, all_numeric = depth_and_all_numeric(obj, 0)
        # treat as multidimensional if depth > 1 and all leaves numeric
        return all_numeric and depth > 1

    # Check order: labeled 1D first, then explicit multidimensional array/tensor, then nested multidimensional sequences,
    # then native python sequences (1D)
    if is_one_dim_labeled(var0):
        return True, 'one_dim_labeled'

    if is_numpy_multidim(var0) or is_torch_multidim(var0) or nested_numeric_depth_gt_one(var0):
        return True, 'multidim_numeric'

    if is_native_sequence(var0):
        return True, 'native_sequence'

    return False, None


