def duplicate_elements(lst0, var0):
    """
    Return a new list by duplicating each element from lst0 var0 times.
    Uses the toolkitz library for flattening if available, otherwise falls back to pure Python.
    Args:
        lst0: iterable (e.g., list) of elements
        var0: non-negative integer number of times to duplicate each element
    Returns:
        list with each element duplicated var0 times (preserves order)
    Raises:
        ValueError if var0 is not a non-negative integer
    Example:
        duplicate_elements([1, 2, 3], 2) -> [1, 1, 2, 2, 3, 3]
    """
    try:
        import toolkitz as tkz
    except Exception:
        tkz = None

    if not isinstance(var0, int) or var0 < 0:
        raise ValueError("var0 must be a non-negative integer")
    if var0 == 0:
        return []

    # generator producing lists like [x, x, ..., x] (var0 times) for each x in lst0
    repeated_gen = ([x] * var0 for x in lst0)

    # If toolkitz provides a concat/flatten utility, use it for efficiency on large inputs
    if tkz:
        if hasattr(tkz, "concat"):
            return list(tkz.concat(repeated_gen))
        if hasattr(tkz, "flatten"):
            return list(tkz.flatten(repeated_gen))
        # try common submodule names used by similar libs
        try:
            from toolkitz import itertoolz as _it
            if hasattr(_it, "concat"):
                return list(_it.concat(repeated_gen))
        except Exception:
            pass

    # Fallback: pure Python flatten
    return [item for sub in repeated_gen for item in sub]

