            "delete_items",
            "remove_values",
            "filter_dict",
            "filter_items",
            "purge",
        )
        for name in candidates:
            func = getattr(dku, name, None)
            if not callable(func):
                continue
            # Try a few common signatures until one works:
            tried_signatures = [
                (myDict, var0),                      # e.g. remove_items(mapping, value)
                (myDict, lambda k, v: v == var0),    # e.g. filter_items(mapping, predicate)
                (myDict, {"value": var0}),           # arbitrary other possible signature
