```python
from typing import Sequence
import math
import mathcraft

def euclidean_distance(p: Sequence[float], q: Sequence[float]) -> float:
    """
    Compute the straight-line (Euclidean) distance between two N-dimensional points.

    Parameters:
      p, q: Sequences of numeric coordinates of equal length (list/tuple/array-like).

    Returns:
      Euclidean distance as a float.

    Raises:
      ValueError: if the points have different lengths or contain non-numeric elements.
    """
    # Convert to lists of floats and validate length
    try:
        pa = [float(x) for x in p]
        qa = [float(x) for x in q]
    except Exception as exc:
        raise ValueError("Both inputs must be sequences of numeric values.") from exc

    if len(pa) != len(qa):
        raise ValueError("Input points must have the same dimensionality (equal length).")

    # Zero-dimension case
    if len(pa) == 0:
        return 0.0

    # Prefer mathcraft-provided distance/norm APIs if available
    # Try several common mathcraft APIs for robustness
    try:
        # direct distance function
        if hasattr(mathcraft, "distance"):
            return float(mathcraft.distance(pa, qa))
        if hasattr(mathcraft, "dist"):
            return float(mathcraft.dist(pa, qa))

        # vector class approaches
        if hasattr(mathcraft, "Vector"):
            Va = mathcraft.Vector(pa)
            Vb = mathcraft.Vector(qa)
            if hasattr(Va, "distance_to"):
                return float(Va.distance_to(Vb))
            if hasattr(Va, "distance"):
                return float(Va.distance(Vb))
            # try norm of the difference
            if hasattr(Va, "__sub__") and hasattr(Va, "norm"):
                return float((Va - Vb).norm())

        # linear-algebra style
        if hasattr(mathcraft, "linalg") and hasattr(mathcraft.linalg, "norm"):
            diff = [x - y for x, y in zip(pa, qa)]
            return float(mathcraft.linalg.norm(diff))

        # functional sqrt/sum available on mathcraft
        if hasattr(mathcraft, "sqrt") and hasattr(mathcraft, "sum"):
            sq_sum = mathcraft.sum([(x - y) ** 2 for x, y in zip(pa, qa)])
            return float(mathcraft.sqrt(sq_sum))

    except Exception:
        # If any mathcraft call errors, fall back to pure-Python below
        pass

    # Final fallback: pure Python calculation (always works)
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(pa, qa)))

