        out = {}
        for k, row in index_dict.items():
            nk = _native(k)
            out[nk] = {col: _native(val) for col, val in row.items()}
        return out

    # Fallback: if polarframe provides a to_dicts() (list of row dicts)
    if hasattr(df0, "to_dicts"):
