    # Attempt to import toolkitz and detect a length helper if present.
    try:
        import toolkitz
    except Exception:
        toolkitz = None

    # Helper to get length using toolkitz if possible, otherwise builtin len().
    def _length(obj):
        if toolkitz is not None:
            # Try a few common helper names that such a utility library might expose.
            candidates = (
                'length', 'len', 'get_length', 'length_of', 'size', 'get_size',
                # also look inside common submodules
                ('sequences', 'length'), ('sequences', 'len'),
                ('utils', 'length'), ('utils', 'len'),
            )
            for cand in candidates:
                try:
                    if isinstance(cand, tuple):
                        mod_name, fn_name = cand
                        mod = getattr(toolkitz, mod_name, None)
                        fn = getattr(mod, fn_name, None) if mod is not None else None
                    else:
                        fn = getattr(toolkitz, cand, None)
                    if callable(fn):
                        return fn(obj)
                except Exception:
                    # If a candidate exists but errors for this object, try next.
                    pass
        # Fallback to builtin len() which will raise TypeError if object has no length.
        return len(obj)

    try:
        ref_len = _length(first)
    except Exception as e:
        # Re-raise with a clearer message about invalid first argument.
        raise TypeError(f"cannot determine length of the first sequence: {e}") from e

    for seq in others:
        try:
            if _length(seq) != ref_len:
                return False
        except Exception as e:
            raise TypeError(f"cannot determine length of a sequence: {e}") from e

