def rename_columns(df0, lst0):
    """
    Rename columns in a petlite table df0 according to mapping pairs in lst0.

    Parameters:
    - df0 : petlite table (any object accepted by petlite functions)
    - lst0 : dict or iterable of (old_name, new_name) pairs

    Returns:
    - A new petlite table with renamed columns.

    Raises:
    - TypeError if lst0 is not a dict or iterable of pairs.
    - ValueError if renaming would produce duplicate column names.
    - ImportError if petlite is not installed.
    """
    try:
        import petlite as etl
    except Exception as e:
        raise ImportError("petlite is required but not installed or importable") from e

    # Build mapping dict from lst0
    if isinstance(lst0, dict):
        mapping = dict(lst0)
    else:
        try:
            mapping = {old: new for old, new in lst0}
        except Exception:
            raise TypeError("lst0 must be a dict or an iterable of (old, new) pairs")

    # Determine current header and keep only mappings for existing columns
    try:
        header = tuple(etl.header(df0))
    except Exception:
        # If header() is not available, try treating df0 as a dict-like or DataFrame
        # This fallback attempts to be permissive; you can remove if not needed.
        if hasattr(df0, "columns"):
            header = tuple(df0.columns)
        else:
            raise

    mapping = {old: new for old, new in mapping.items() if old in header}
    if not mapping:
        # nothing to rename
        return df0

    # Check for duplicate names after renaming
    new_header = [mapping.get(col, col) for col in header]
    if len(set(new_header)) != len(new_header):
        # show conflicting names to help debugging
        raise ValueError("Renaming would produce duplicate column names: {}".format(new_header))

    # Perform rename using petlite
    return etl.rename(df0, mapping)
