import statistics
from typing import Mapping, Any, Iterable, Dict, Optional

def compute_means(dict0: Mapping[Any, Iterable[float]]) -> Dict[Any, Optional[float]]:
    """
    Compute the mean of the numeric values for each key in dict0 using the statistics library.
    Returns a new dict mapping each key to its mean (float). If a value sequence is empty,
    not iterable, or contains non-numeric elements, the corresponding result is None.

    Example:
        compute_means({'a': [1, 2, 3], 'b': [4.0], 'c': []})
        -> {'a': 2.0, 'b': 4.0, 'c': None}
    """
    result: Dict[Any, Optional[float]] = {}
    for key, values in dict0.items():
        # Try to turn values into a list (catches non-iterables)
        try:
            seq = list(values)
        except TypeError:
            result[key] = None
            continue

        if not seq:
            result[key] = None
            continue

        try:
            result[key] = statistics.mean(seq)
        except (TypeError, statistics.StatisticsError):
            # TypeError: non-numeric items in seq
            # StatisticsError: should not occur here because we checked length, but kept for safety
            result[key] = None

    return result

