def sum_filtered(table, column, filter_expr):
    """
    Sum numeric values in a specified column for all rows that satisfy a filter expression.

    Parameters
    - table: a petl-style table (header row followed by data rows), OR any iterable where the first
             row is a header and subsequent rows are sequences, OR an iterable of dicts (each dict
             maps column names to values).
             The function will try to use petltools (or petl) helpers if available.
    - column: name of the column to sum (string). Using a header name is recommended.
    - filter_expr: a Python expression (string) used to filter rows. The expression is evaluated
                   for each row. Column names that are valid Python identifiers may be used
                   directly (e.g. "age > 30"). All rows are also provided as `row`, so you
                   can use bracket notation for any column name (e.g. "int(row['Total Sales']) > 1000").
                   Example expressions: "age >= 18 and city == 'NY'", "float(row['amount'])>0".

    Returns
    - float: sum of the values in the specified column for rows where the filter expression is True.

    Notes / safety:
    - The filter expression is evaluated with eval() but with a restricted set of builtins
      to reduce risk. It still executes Python code, so only use trusted expressions.
    - The function attempts to use petltools.dicts (or petl.dicts) to iterate rows as dicts.
      If not available, it will fall back to interpreting the input as (header, rows...).
    """

    # Try to import petltools, otherwise fall back to petl if available.
    try:
        import petltools as _pt  # preferred by the user request
    except Exception:
        try:
            import petl as _pt
        except Exception:
            _pt = None

    # Helper: obtain an iterator of row dictionaries (column-name -> value).
    def _row_dicts_from_table(tbl):
        # If tbl is already an iterable of dicts, detect and yield them.
        try:
            # Peek first element safely if it's an iterator
            it = iter(tbl)
        except TypeError:
            raise TypeError("table must be an iterable (petl table, iterable of rows, or iterable of dicts)")
        # Try to detect dicts without consuming the iterable permanently
        try:
            # If tbl is a sequence (list/tuple), we can check the first element easily
            if not hasattr(tbl, '__iter__') or hasattr(tbl, '__next__'):
                # tbl is an iterator; convert to list temporarily (small tables only)
                tbl_list = list(tbl)
                if not tbl_list:
                    return iter(())
                first = tbl_list[0]
                if isinstance(first, dict):
                    return iter(tbl_list)
                # assume header + rows
                header = first
                return (dict(zip(header, row)) for row in tbl_list[1:])
            else:
                # tbl is a sequence (e.g., list). Inspect first element
                first = tbl[0]
                if isinstance(first, dict):
                    return iter(tbl)
                # assume header + rows
                header = first
                return (dict(zip(header, row)) for row in tbl[1:])
        except Exception:
            # As a more robust fallback, try to use petl/petltools helpers if present
            if _pt is not None:
                try:
                    # petl.dicts yields dicts for each row
                    return _pt.dicts(tbl)
                except Exception:
                    pass
            # Final fallback: iterate manually
            it = iter(tbl)
            try:
                header = next(it)
            except StopIteration:
                return iter(())
            return (dict(zip(header, row)) for row in it)

    # Prepare the row-dicts iterator
    rowdicts = _row_dicts_from_table(table)

    # Compile the filter expression once
    try:
        compiled_expr = compile(filter_expr, "<filter_expr>", "eval")
    except Exception as e:
        raise ValueError("Invalid filter expression: {}".format(e))

    # Restrict available builtins but allow a few safe converters
    safe_builtins = {
        'int': int,
        'float': float,
        'str': str,
        'len': len,
        'abs': abs,
        'min': min,
        'max': max,
        'round': round,
    }
    eval_globals = {'__builtins__': None}
    # Allow some helper names in globals (safe functions)
    eval_globals.update(safe_builtins)

    total = 0.0
    for row in rowdicts:
        # row should be a dict mapping column names to values; ensure we have that
        if not isinstance(row, dict):
            # As a defensive fallback, attempt to convert sequence rows to dict by using header
            # If this happens, it's unlikely because _row_dicts_from_table tries to return dicts.
            try:
                # try to use petl header if available
                if _pt is not None:
                    hdr = _pt.header(table)
                    row = dict(zip(hdr, row))
                else:
                    # can't determine header; skip this row
                    continue
            except Exception:
                continue

        # Provide both direct name access (for valid identifiers) and a 'row' dict for bracket access
        eval_locals = {}
        # Only include keys that are valid identifiers in locals (so eval can use them)
        for k, v in row.items():
            if isinstance(k, str) and k.isidentifier():
                eval_locals[k] = v
        eval_locals['row'] = row

        # Evaluate condition
        try:
            cond = bool(eval(compiled_expr, eval_globals, eval_locals))
        except Exception:
            # If evaluation fails for this row, treat as not matching
            cond = False

        if not cond:
            continue

        # Extract the value from the specified column
        try:
            value = row.get(column, None)
        except Exception:
            # If row is not a dict-like, skip
            value = None

        if value is None or value == '':
            # treat missing/empty as zero / skip
            continue

        # Convert to float (allow ints)
        try:
            num = float(value)
        except Exception:
            # Try to use safe converter if value is string with commas, currency, etc.
            try:
                cleaned = str(value).replace(',', '').replace('$', '')
                num = float(cleaned)
            except Exception:
                raise ValueError("Could not convert value {!r} in column {!r} to float".format(value, column))
        total += num

    return total

