def row_in_array(row0, arr0, rtol=1e-8, atol=1e-12):
    """
    Return True if the 1D sequence `row0` is present as a row in the 2D sequence `arr0`.
    Uses scipy (scipy.spatial.distance.cdist) for numeric comparisons with tolerance.
    Accepts Python sequences (lists, tuples) or numpy arrays.

    Parameters:
      row0: 1D sequence-like (list, tuple, numpy array)
      arr0: 2D sequence-like (list of lists, 2D numpy array)
      rtol, atol: tolerances passed to numpy.isclose (useful for floating-point rows)

    Returns:
      bool: True if an equal (within tolerance for numeric) row exists in arr0, else False
    """
    import numpy as np
    try:
        from scipy.spatial.distance import cdist
    except Exception as e:
        raise ImportError("scipy is required by this function (scipy.spatial.distance.cdist).") from e

    row = np.asarray(row0)
    arr = np.asarray(arr0)

    if row.ndim != 1:
        raise ValueError("row0 must be one-dimensional")
    if arr.ndim != 2:
        raise ValueError("arr0 must be two-dimensional")
    if arr.shape[1] != row.shape[0]:
        return False

    # Prefer numeric tolerant comparison using distances (handles floats)
    try:
        # cdist(arr, row.reshape(1,-1)) -> distances of each row in arr to row
        dists = cdist(arr, row.reshape(1, -1), metric='euclidean').ravel()
        return bool(np.any(np.isclose(dists, 0.0, rtol=rtol, atol=atol)))
    except Exception:
        # Fallback for non-numeric / object arrays: exact elementwise equality
        # Compare each row with `row` using elementwise equality
        for r in arr:
            try:
                if np.array_equal(r, row):
                    return True
            except Exception:
                # last fallback: Python-level comparison
                if list(r) == list(row):
                    return True
        return False

# Example usage:
# row_in_array([1,2,3], [[0,1,2],[1,2,3],[3,4,5]])  -> True
# row_in_array([1.0,2.0], [[1.0,2.0000000001]])      -> True (within default tolerance)

