The function attempts to use cytoolkit helpers when available (non-breaking: it falls back to safe local implementations if cytoolkit does not provide the expected helpers). It preserves the input type: if dict0 is a mapping it returns an OrderedDict with items in the requested order; if dict0 is a sequence it returns a list of records in the requested order.

```python
from collections import OrderedDict
from collections.abc import Mapping, Sequence
import cytoolkit

def sort_records_by_reference(dict0, lst0, var0, missing_to_end=True):
    """
    Sort records in dict0 according to order defined by lst0 using the value at key var0.

    Parameters
    - dict0: mapping (dict-like) or sequence (list/tuple) of records (record is typically a dict)
             If dict0 is a mapping, the returned value will be an OrderedDict preserving keys with
             values sorted by the record's var0 value. If dict0 is a sequence, a list is returned.
    - lst0: sequence that defines desired order. Values in records[var0] are matched against items of lst0.
    - var0: key (or dot-separated path) to read from each record to get the sort value.
            Example: 'status' or 'meta.type' to follow nested dicts/lists.
    - missing_to_end: if True, records whose var0 value is NOT found in lst0 are placed after all matched items;
                      if False they are placed before matched items.

    Returns
    - OrderedDict (if input was a Mapping) or list (if input was a Sequence) of records sorted by lst0 order.
    """

    # Build lookup map from lst0 value -> index (first occurrence wins)
    index_map = {}
    for i, v in enumerate(lst0):
        if v not in index_map:
            index_map[v] = i

    # Try to use cytoolkit helpers for safe lookup if present, otherwise use a fallback
    get_in = None
    if hasattr(cytoolkit, "get_in"):
        get_in = cytoolkit.get_in
    elif hasattr(cytoolkit, "get"):
        # if cytoolkit.get supports nested keys with dot-separated paths, use it; we'll still fallback.
        get_in = cytoolkit.get

    def _get_value(record, path):
        """
        Extract value from record given path which can be:
         - a single key (str/int)
         - a dot-separated path for nested dict/list access, e.g. "a.b.0.c"
         - an integer index if record is sequence and path is int
        """
        # If cytoolkit provides a compatible helper, use it and catch exceptions
        if get_in is not None:
            try:
                return get_in(record, path)
            except Exception:
                pass

        # Local fallback implementation
        if path is None:
            return None

        # If path is an int, try direct index
        if isinstance(path, int):
            try:
                return record[path]
            except Exception:
                return None

        # If path is not a string, attempt simple get
        if not isinstance(path, str):
            try:
                return record[path]
            except Exception:
                return None

        # Dot-separated navigation
        parts = path.split(".")
        cur = record
        for p in parts:
            if cur is None:
                return None
            # try integer index
            if isinstance(cur, (list, tuple)) and p.isdigit():
                idx = int(p)
                if 0 <= idx < len(cur):
                    cur = cur[idx]
                else:
                    return None
            else:
                # mapping access
                try:
                    if isinstance(cur, Mapping):
                        cur = cur.get(p)
                    else:
                        # try attribute or index
                        try:
                            cur = getattr(cur, p)
                        except Exception:
                            try:
                                cur = cur[p]
                            except Exception:
                                return None
                except Exception:
                    return None
        return cur

    # Build list of (key, record) pairs if input is mapping, or list of (original_index, record) if sequence
    items = []
    if isinstance(dict0, Mapping):
        for k, rec in dict0.items():
            items.append((k, rec))
        is_mapping = True
    elif isinstance(dict0, Sequence) and not isinstance(dict0, (str, bytes)):
        for idx, rec in enumerate(dict0):
            items.append((idx, rec))
        is_mapping = False
    else:
        raise TypeError("dict0 must be a mapping or a sequence of records")

    # Create a large sentinel index for missing values
    missing_index_base = len(lst0) + (0 if missing_to_end else -len(lst0) - 1)

    # Compute sort key for each item
    def _sort_key(pair_with_id):
        _, rec = pair_with_id
        v = _get_value(rec, var0)
        # If v is an iterable of values (e.g. list) we choose first match in lst0 (if any)
        chosen_index = None
        if isinstance(v, (list, tuple, set)):
            for elem in v:
                if elem in index_map:
                    chosen_index = index_map[elem]
                    break
        else:
            chosen_index = index_map.get(v)

        if chosen_index is not None:
            return (0, chosen_index)  # matched items come first (0 group), then by index
        else:
            # unmatched items: either put after all matched (missing_to_end True) or before (False)
            if missing_to_end:
                # put after matched; preserve stable order using second element (original position)
                return (1, )
            else:
                # put before matched
                return (-1, )

    # Stable sort using Python's sorted
    sorted_items = sorted(items, key=_sort_key)

    # Prepare return preserving input type
    if is_mapping:
        out = OrderedDict()
        for k, rec in sorted_items:
            out[k] = rec
        return out
    else:
        return [rec for _, rec in sorted_items]
