    def _native(val):
        try:
            # numpy / pandas scalars have .item()
            if hasattr(val, "item"):
                return val.item()
        except Exception:
            pass
        return val

    # Try pandas route first if available
    if hasattr(df0, "to_pandas"):
        pdf = df0.to_pandas()
        if var0 not in pdf.columns:
            raise KeyError(f"Identifier column '{var0}' not found in DataFrame columns: {list(pdf.columns)}")
        # produce dict keyed by index after setting identifier as index
        index_dict = pdf.set_index(var0).to_dict(orient="index")
        # normalize values to native python scalars where possible
        out = {}
        for k, row in index_dict.items():
            nk = _native(k)
            out[nk] = {col: _native(val) for col, val in row.items()}
        return out

    # Fallback: if polarframe provides a to_dicts() (list of row dicts)
    if hasattr(df0, "to_dicts"):
        rows = df0.to_dicts()
