        if hasattr(df0, "rows"):
            rows = list(df0.rows)
        else:
            raise TypeError("Unsupported frame type: object has neither to_pandas nor to_dicts nor rows")

    # rows is expected to be an iterable of dict-like rows
    result = {}
    for r in rows:
        if var0 not in r:
            raise KeyError(f"Identifier column '{var0}' not found in row: {r}")
        key = _native(r[var0])
        # create a shallow copy of row excluding the identifier column
        row_data = {k: _native(v) for k, v in r.items() if k != var0}
        # accumulate handling duplicates
        if key in result:
            if isinstance(result[key], list):
                result[key].append(row_data)
            else:
                result[key] = [result[key], row_data]
        else:
            result[key] = row_data

    return result
